/** The short human name a handoff's thread gets, generated by omp's own session-title generator. */

import type { Settings } from "@oh-my-pi/pi-coding-agent";
import type { ModelRegistry } from "@oh-my-pi/pi-coding-agent/config/model-registry";
import { generateSessionTitle } from "@oh-my-pi/pi-coding-agent/utils/title-generator";

/** Longest the service accepts, in code points. */
export const NAME_MAX = 60;
/** How long a handoff waits for a name. */
export const NAME_TIMEOUT_MS = 8000;

/** omp's session-title generator; the seam tests replace. */
export type TitleGenerator = typeof generateSessionTitle;

/** Icon and emoji glyphs (Nerd Fonts live in the private-use area), quotes and spaces in front of a title. */
const LEADING_NOISE = /^[\s"'`“”‘’«»\p{Extended_Pictographic}\p{So}\p{Co}\p{Mn}\u200d\ufe0f]+/u;
const TRAILING_NOISE = /[\s"'`“”‘’«»,;:.\-–—]+$/u;

/** `raw` as the service takes a name: one line without icons or quotes, at most {@link NAME_MAX} code points, cut at a word boundary. `""` when nothing is left. */
export function cleanName(raw: string): string {
	const oneLine = raw.replace(/[\p{Cc}\s]+/gu, " ").trim();
	const bare = oneLine.replace(LEADING_NOISE, "");
	const points = [...bare];
	if (points.length <= NAME_MAX) return bare.replace(TRAILING_NOISE, "");
	const head = points.slice(0, NAME_MAX);
	const wholeWord = /\s/u.test(points[NAME_MAX] ?? "");
	const lastSpace = head.lastIndexOf(" ");
	const cut = wholeWord || lastSpace <= 0 ? head : head.slice(0, lastSpace);
	return cut.join("").replace(TRAILING_NOISE, "");
}

export interface NameInput {
	task: string;
	/** Absent only in test doubles; without it there is nothing to ask. */
	registry: ModelRegistry | undefined;
	settings: Settings;
	/** The session's model: titling falls back to it when no tiny, commit or smol model is configured. */
	model: { provider: string; id: string } | undefined;
	/** The launch's own signal: a finished or failed launch stops the request. */
	signal: AbortSignal;
	timeoutMs?: number;
}

/**
 * A name for `task`, or `""` when none came: omp has no title model, the generator declined (a greeting, a
 * request too vague to name), it failed, or {@link NAME_TIMEOUT_MS} (or the launch) ran out first. Never throws:
 * a handoff does not depend on its name.
 */
export async function generateName(input: NameInput, generate: TitleGenerator = generateSessionTitle): Promise<string> {
	const { registry } = input;
	if (!registry || input.signal.aborted) return "";
	const signal = AbortSignal.any([input.signal, AbortSignal.timeout(input.timeoutMs ?? NAME_TIMEOUT_MS)]);
	// The generator honours the signal, but a stuck one must not hold the handoff: the race ends it too.
	const cutOff = new Promise<null>(resolve => signal.addEventListener("abort", () => resolve(null), { once: true }));
	try {
		const current = input.model ? registry.find(input.model.provider, input.model.id) : undefined;
		const title = await Promise.race([generate(input.task, registry, input.settings, undefined, current, undefined, undefined, signal), cutOff]);
		return title === null ? "" : cleanName(title);
	} catch {
		return "";
	}
}
